{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Pharmacokinetic studies in mice showed that 6-MOMIPP, a harmine-based analogue sharing the methoxy-methyl-pyridoindole core, reaches brain concentrations that mirror plasma, indicating ready BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "MOMIPP readily crosses the BBB in mice, with brain concentrations approximately 50–60% of plasma up to 8 hours after administration, directly demonstrating meaningful CNS access for a close harmine analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "6-MeO-THBC penetrated the BBB poorly after IV injection in mice, but this tetrahydro-beta-carboline lacks the aromatic pyridine ring of the query and is therefore a weaker transferable negative control.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "O-methyl-[11C]bufotenine, a methoxyindole analogue, showed brain/blood radioactivity ratios greater than 1 up to 60 minutes in mice, supporting CNS access for methoxyindole-containing compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "PET studies in humans confirmed that melatonin, a 5-methoxyindole, crosses the BBB, supporting the CNS-penetrant character of the shared methoxyindole motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "[18F]T807 (flortaucipir), a pyridoindole-based PET tracer, showed rapid brain penetration with maximal uptake of 4.16% ID/g at 2 minutes in mice, supporting CNS access for the pyridoindole scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "A diarylindole-sulfonamide compound showed only very low brain uptake despite lipophilicity, but its polar sulfonamide and distant structure limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is harmine, a fully aromatic beta-carboline. Direct in vivo evidence from close harmine analogues (6-MOMIPP and MOMIPP) shows brain concentrations mirroring or reaching 50–60% of plasma in mice, and multiple methoxyindole/pyridoindole CNS-active compounds (5-MeO-DMT, melatonin, flortaucipir) support good BBB penetration. The negative evidence comes from structurally distant or saturated analogues, so the overall transfer supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct quantitative Kp,uu or human PET data for harmine itself are included.",
    "Most direct evidence is from close analogues in mice rather than the exact query molecule.",
    "Efflux-transporter status for harmine is not explicitly reported, though abundant in vivo brain uptake in analogues mitigates this uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

